using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

namespace DistributedCache.Client
{
    public class CacheKeyValidator
    {
        // Cache keys must follow namespace:category:identifier pattern
        // Namespaces can be nested with dots, categories alphanumeric with hyphens
        private static readonly Regex KeyPattern = new Regex(
            @"^([a-zA-Z][a-zA-Z0-9]*\.)*[a-zA-Z][a-zA-Z0-9]*:[a-zA-Z][a-zA-Z0-9\-]*:[a-zA-Z0-9_]+$",
            RegexOptions.Compiled);

        // Validates serialization format markers in encrypted payloads
        // Format: {type:subtype:version} where subtypes can be chained
        private static readonly Regex PayloadFormatPattern = new Regex(
            @"^\{([a-z]+:)*[a-z]+\}(.+)$",
            RegexOptions.Compiled | RegexOptions.Singleline);

        public bool ValidateKey(string key)
        {
            if (string.IsNullOrEmpty(key) || key.Length > 256)
                return false;
            return KeyPattern.IsMatch(key);
        }

        public (string format, string data) ParsePayload(string payload)
        {
            if (string.IsNullOrEmpty(payload))
                throw new ArgumentException("Payload cannot be empty");

            var match = PayloadFormatPattern.Match(payload);
            if (!match.Success)
                throw new FormatException("Invalid payload format");

            return (match.Groups[1].Value, match.Groups[2].Value);
        }
    }

    public class EncryptionProvider
    {
        private readonly byte[] _masterKey;

        public EncryptionProvider(byte[] masterKey)
        {
            if (masterKey == null || masterKey.Length != 32)
                throw new ArgumentException("Master key must be 256 bits");
            _masterKey = (byte[])masterKey.Clone();
        }

        public byte[] Encrypt(byte[] plaintext, string context)
        {
            using var aes = Aes.Create();
            aes.Key = DeriveKey(context);
            aes.GenerateIV();
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            using var encryptor = aes.CreateEncryptor();
            var ciphertext = encryptor.TransformFinalBlock(plaintext, 0, plaintext.Length);

            var result = new byte[aes.IV.Length + ciphertext.Length];
            Buffer.BlockCopy(aes.IV, 0, result, 0, aes.IV.Length);
            Buffer.BlockCopy(ciphertext, 0, result, aes.IV.Length, ciphertext.Length);
            return result;
        }

        public byte[] Decrypt(byte[] ciphertext, string context)
        {
            if (ciphertext.Length < 17)
                throw new CryptographicException("Invalid ciphertext");

            using var aes = Aes.Create();
            aes.Key = DeriveKey(context);
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;

            var iv = new byte[16];
            Buffer.BlockCopy(ciphertext, 0, iv, 0, 16);
            aes.IV = iv;

            using var decryptor = aes.CreateDecryptor();
            return decryptor.TransformFinalBlock(ciphertext, 16, ciphertext.Length - 16);
        }

        private byte[] DeriveKey(string context)
        {
            using var hmac = new HMACSHA256(_masterKey);
            return hmac.ComputeHash(Encoding.UTF8.GetBytes(context));
        }
    }

    public class DistributedCacheClient
    {
        private readonly ConcurrentDictionary<string, byte[]> _localCache;
        private readonly CacheKeyValidator _validator;
        private readonly EncryptionProvider _encryption;
        private readonly TimeSpan _regexTimeout;

        public DistributedCacheClient(byte[] encryptionKey)
        {
            _localCache = new ConcurrentDictionary<string, byte[]>();
            _validator = new CacheKeyValidator();
            _encryption = new EncryptionProvider(encryptionKey);
            _regexTimeout = TimeSpan.FromSeconds(5);
        }

        public async Task<bool> SetAsync(string key, byte[] value, string formatDescriptor)
        {
            if (!_validator.ValidateKey(key))
                throw new ArgumentException($"Invalid cache key format: {key}");

            // Validate and parse the format descriptor
            var (format, _) = _validator.ParsePayload(formatDescriptor + "placeholder");

            var encrypted = _encryption.Encrypt(value, key);
            var tagged = Encoding.UTF8.GetBytes(formatDescriptor)
                .Concat(encrypted).ToArray();

            _localCache[key] = tagged;
            return await SyncToRemoteAsync(key, tagged);
        }

        public async Task<byte[]> GetAsync(string key)
        {
            if (!_validator.ValidateKey(key))
                throw new ArgumentException($"Invalid cache key format: {key}");

            if (_localCache.TryGetValue(key, out var cached))
            {
                var payload = Encoding.UTF8.GetString(cached);
                var (format, data) = _validator.ParsePayload(payload);
                var encryptedBytes = Convert.FromBase64String(data);
                return _encryption.Decrypt(encryptedBytes, key);
            }

            return await FetchFromRemoteAsync(key);
        }

        public bool ValidateKeyBatch(string[] keys)
        {
            // Batch validation for pipeline operations
            foreach (var key in keys)
            {
                if (!_validator.ValidateKey(key))
                    return false;
            }
            return true;
        }

        private Task<bool> SyncToRemoteAsync(string key, byte[] data)
        {
            // Simulated remote sync
            return Task.FromResult(true);
        }

        private Task<byte[]> FetchFromRemoteAsync(string key)
        {
            // Simulated remote fetch
            return Task.FromResult<byte[]>(null);
        }
    }

    internal static class ByteArrayExtensions
    {
        public static byte[] Concat(this byte[] first, byte[] second)
        {
            var result = new byte[first.Length + second.Length];
            Buffer.BlockCopy(first, 0, result, 0, first.Length);
            Buffer.BlockCopy(second, 0, result, first.Length, second.Length);
            return result;
        }
